CREATE TABLE T_CUSTOMER (
    customer_no INTEGER PRIMARY KEY,
    cust_group INTEGER,
    cust_type INTEGER,
    prefix INTEGER,
    fname TEXT,
    mname TEXT,
    lname TEXT,
    suffix INTEGER,
    sex TEXT,
    name_status INTEGER,
    prefix2 INTEGER,
    fname2 TEXT,
